const tenant_id = $input.first().json.tenant_id || 'default';
const platform = $input.first().json.platform || 'linkedin';
const topic_hint = $input.first().json.topic_hint || 'CI/CD';
const trace_id = $input.first().json.trace_id || 'tr_' + Date.now();
return [{ json: { tenant_id, platform, topic_hint, trace_id } }];

const items = $input.all();
const d = items[0].json;
const context_brief = { relevant_signals: [], recommended_angle: 'Lead with speed and scale.', risks: [], opportunities: ['DevOps efficiency'], timestamp: new Date().toISOString() };
return [{ json: { ...d, context_brief } }];

const items = $input.all();
