const content_brief = { headline: 'How we cut deployment time by 40%', key_message: 'Standardizing on one pipeline helps teams ship faster.', hook_type: 'question', hook_text: 'What if you could ship twice as fast without hiring?', cta: 'Try the free tier—no credit card required.', platform_notes: { max_length: 3000 }, timestamp: new Date().toISOString() };
